script:
window.render = t => {
  const ease = x => x < 0 ? 0 : x > 1 ? 1 : 1 - Math.pow(1 - x, 3);
  document.querySelectorAll('.sc').forEach(e => {
    const a = +e.dataset.a, b = +e.dataset.b, i = ease((t - a) / .4), o = ease((b - t) / .3), v = Math.min(i, o);
    e.style.opacity = t < a || t > b ? 0 : v; e.style.transform = `translateY(${(1 - i) * 40}px)`;
  });
  document.querySelectorAll('.cnt').forEach(e => {
    const k = ease((t - +e.dataset.a) / (+e.dataset.d)), v = Math.round(+e.dataset.to * k);
    e.textContent = '€' + v.toLocaleString('en-US');
  });
  document.querySelectorAll('.grow').forEach(e => { e.style.width = (ease((t - +e.dataset.a) / (+e.dataset.d)) * +e.dataset.w) + '%'; });
};
